    entidades: [],
    aeo: [{"pergunta":"O que aconteceu?","resposta":"Alice Huang, a suposta espiã chinesa no centro do escândalo que derrubou o CEO da Nvidia , deixou Cingapura em fevereiro e foi proibida de retornar ao país após uma investigação sobre possíveis crimes , informou o Ministério do Interior cingalês nesta quinta-feira (12)."},{"pergunta":"Qual é o ponto principal?","resposta":"A gigante americana de semicondutores anunciou na quinta-feira (12) que Jensen Huang, seu cofundador e diretor executivo, estava se demitindo do cargo, após relatos de que o executivo de 63 anos teve dois casos extraconjugais, incluindo um com Alice Huang, suspeita pelas autoridades americanas de espionagem para Pequim."},{"pergunta":"Quais são os dados mais importantes?","resposta":"O ministério informou que Alice Huang , ex-executiva da Megaspeed, cliente da Nvidia, foi investigada por possíveis crimes, incluindo a compra de servidores que foram exportados via Singapura para a Malásia sem entrar no mercado de Singapura."},{"pergunta":"Qual é o contexto?","resposta":"Ela foi investigada &quot;por suspeita de envolvimento em possíveis crimes em Singapura, dada a sua posição como então CEO, Presidente do Conselho e uma das principais controladoras da Megaspeed&quot;, afirmou o ministério em comunicado."},{"pergunta":"Quais são os próximos desdobramentos?","resposta":"O ministério acrescentou que a investigação não diz respeito a espionagem."}],
